  let locale='en', userName='', preferences={locale:'en',displayName:'',introComplete:false}, introIndex=0;
  const originals=new WeakMap(), attrOriginals=new WeakMap(), ignored='#preview,#translation,#review-text,#review-messages,#inspect-original,#inspect-crop,#inspect-translation,#review-names,#print-area,[contenteditable="true"],script,style,code,pre';
  function translateTextNode(node){const parent=node.parentElement;if(!parent||parent.closest(ignored)||parent.closest('[data-no-translate]'))return;let source=originals.get(node);if(source===undefined){source=node.nodeValue;originals.set(node,source);}const trimmed=source.trim();if(!trimmed)return;const translated=dictionaries[locale]?.[trimmed]||trimmed;const left=source.match(/^\s*/)?.[0]||'',right=source.match(/\s*$/)?.[0]||'';const value=left+translated+right;if(node.nodeValue!==value)node.nodeValue=value;}
  function translateAttributes(root=document){root.querySelectorAll?.('[placeholder],[aria-label],[title]').forEach(el=>{if(el.closest(ignored))return;let saved=attrOriginals.get(el);if(!saved){saved={};attrOriginals.set(el,saved);}for(const attr of ['placeholder','aria-label','title']){if(!el.hasAttribute(attr))continue;if(saved[attr]===undefined)saved[attr]=el.getAttribute(attr);const value=saved[attr],translated=dictionaries[locale]?.[value]||value;if(el.getAttribute(attr)!==translated)el.setAttribute(attr,translated);}});}
  function apply(root=document.body){if(!root)return;const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let node;while((node=walker.nextNode()))translateTextNode(node);translateAttributes(root);}
  function setLocale(value){locale=['en','de','ar'].includes(value)?value:'en';document.documentElement.lang=locale;document.documentElement.dir=locale==='ar'?'rtl':'ltr';document.title=locale==='en'?'TranslateOCR · Document translation':locale==='ar'?'TranslateOCR · ترجمة المستندات':'TranslateOCR · Übersetzungsstudio';const picker=document.querySelector('#ui-language');if(picker)picker.value=locale;const introPicker=document.querySelector('#intro-language');if(introPicker){introPicker.value=locale;const names=locale==='ar'?['الإنجليزية','الألمانية','العربية']:locale==='de'?['Englisch','Deutsch','Arabisch']:['English','German','Arabic'];[...introPicker.options].forEach((option,i)=>option.textContent=names[i]);}document.querySelectorAll('.demo-link,.demo-nav').forEach(link=>link.href=`/demo/?lang=${locale}`);apply();if(document.querySelector('#onboarding:not([hidden])'))renderIntro();window.currentInterfaceLanguage=locale;window.dispatchEvent(new Event('translateocr-locale'));return locale;}
  function t(value){return dictionaries[locale]?.[value]||value;}
  const observer=new MutationObserver(records=>{for(const record of records){if(record.type==='characterData')translateTextNode(record.target);else for(const node of record.addedNodes){if(node.nodeType===Node.TEXT_NODE)translateTextNode(node);else if(node.nodeType===Node.ELEMENT_NODE)apply(node);}}});
  function save(){if(typeof window.saveUserPreferences==='function')return window.saveUserPreferences(preferences);return Promise.resolve();}
  function greet(){const box=document.querySelector('#welcome-greeting');if(!box)return;box.setAttribute('data-no-translate','');const salutation=locale==='ar'?'مرحباً':locale==='de'?'Hallo':'Hello';box.textContent=userName?`${salutation}, ${userName}`:`${salutation}!`;box.hidden=false;box.classList.remove('greeting-in');requestAnimationFrame(()=>box.classList.add('greeting-in'));clearTimeout(greet.timer);greet.timer=setTimeout(()=>{box.classList.remove('greeting-in');setTimeout(()=>box.hidden=true,300);},2600);}
  function rememberIntro(){try{sessionStorage.setItem('translateocr-intro-progress',JSON.stringify({step:introIndex,name:document.querySelector('#intro-name').value.trim(),locale}));}catch{}}
  function forgetIntro(){try{sessionStorage.removeItem('translateocr-intro-progress');}catch{}}
  function renderIntro(){const L=introText[locale],step=L.steps[introIndex],first=introIndex===0,last=introIndex===L.steps.length-1;document.querySelector('#intro-eyebrow').textContent=step[0];document.querySelector('#onboarding-title').textContent=step[1];document.querySelector('#onboarding-copy').textContent=step[2];document.querySelector('#intro-fields').hidden=!first;document.querySelector('#intro-skip').textContent=L.skip;document.querySelector('#intro-back').textContent=L.back;document.querySelector('#intro-back').hidden=first;document.querySelector('#intro-next').textContent=last?L.finish:L.next;document.querySelector('#intro-demo').hidden=!last;document.querySelector('#intro-demo').textContent=L.demo;document.querySelector('#intro-name-label').textContent=L.askName;document.querySelector('#intro-name').placeholder=L.namePlaceholder;document.querySelector('#intro-error').textContent='';document.querySelector('#intro-language-label').textContent=L.language;document.querySelector('#intro-progress').setAttribute('aria-label',locale==='de'?'Einführungsfortschritt':locale==='ar'?'تقدم الجولة':'Onboarding progress');document.querySelector('#intro-progress').replaceChildren(...L.steps.map((_,i)=>{const dot=document.createElement('span');dot.className='intro-dot'+(i===introIndex?' active':'');dot.setAttribute('aria-label',`${i+1} / ${L.steps.length}`);return dot;}));window.positionAISetupForTour?.(introIndex);rememberIntro();const art=document.querySelector('#intro-art');art.hidden=introIndex===2;art.dataset.step=String(introIndex);art.classList.remove('intro-art-in');requestAnimationFrame(()=>art.classList.add('intro-art-in'));}
  async function completeIntro(){const name=document.querySelector('#intro-name').value.trim();if(!name){document.querySelector('#intro-error').textContent=locale==='de'?'Bitte gib deinen Namen ein.':locale==='ar'?'أدخل اسمك من فضلك.':'Please enter your name.';document.querySelector('#intro-name').focus();return;}userName=name;preferences={...preferences,locale,displayName:userName,introComplete:true};const button=document.querySelector('#intro-next');button.disabled=true;try{await save();forgetIntro();document.querySelector('#onboarding').hidden=true;window.positionAISetupForTour?.(-1);greet();}catch(error){document.querySelector('#intro-error').textContent=error.message;}finally{button.disabled=false;}}
  function initOnboarding(saved={}){preferences={locale:saved.locale||'en',displayName:saved.displayName||'',introComplete:saved.introComplete===true};userName=preferences.displayName;setLocale(preferences.locale);const overlay=document.querySelector('#onboarding');if(!preferences.introComplete){introIndex=0;try{const progress=JSON.parse(sessionStorage.getItem('translateocr-intro-progress')||'null');if(progress&&Number.isInteger(progress.step)&&progress.step>=0&&progress.step<introText[locale].steps.length){introIndex=progress.step;document.querySelector('#intro-name').value=String(progress.name||'').slice(0,80);setLocale(progress.locale);}}catch{}renderIntro();overlay.hidden=false;requestAnimationFrame(()=>document.querySelector(introIndex===0?'#intro-name':introIndex===2?'#provider-choice':'#intro-next').focus());}else greet();}
  document.querySelector('#ui-language')?.addEventListener('change',async event=>{setLocale(event.target.value);preferences={...preferences,locale};if(typeof window.saveUserPreferences==='function')try{await save();}catch(error){document.querySelector('#connection-error').textContent=error.message;}});
  document.querySelector('#intro-language')?.addEventListener('change',event=>{setLocale(event.target.value);renderIntro();});
  document.querySelector('#intro-demo')?.addEventListener('click',async()=>{preferences={...preferences,locale,displayName:document.querySelector('#intro-name').value.trim()||userName,introComplete:true};userName=preferences.displayName;try{await save();forgetIntro();location.href=`/demo/?lang=${locale}`;}catch(error){document.querySelector('#intro-error').textContent=error.message;}});
  document.querySelector('#intro-next')?.addEventListener('click',()=>{if(introIndex===0&&!document.querySelector('#intro-name').value.trim()){document.querySelector('#intro-error').textContent=locale==='de'?'Bitte gib deinen Namen ein.':locale==='ar'?'أدخل اسمك من فضلك.':'Please enter your name.';document.querySelector('#intro-error').textContent=locale==='de'?'Bitte gib deinen Namen ein.':locale==='ar'?'أدخل اسمك من فضلك.':'Please enter your name.';document.querySelector('#intro-name').focus();return;}document.querySelector('#intro-error').textContent='';if(introIndex===introText[locale].steps.length-1){void completeIntro();return;}introIndex++;renderIntro();});
  document.querySelector('#intro-back')?.addEventListener('click',()=>{introIndex=Math.max(0,introIndex-1);renderIntro();});
  document.querySelector('#intro-skip')?.addEventListener('click',async()=>{preferences={...preferences,locale,displayName:document.querySelector('#intro-name').value.trim()||userName,introComplete:true};userName=preferences.displayName;try{await save();forgetIntro();document.querySelector('#onboarding').hidden=true;window.positionAISetupForTour?.(-1);greet();}catch(error){document.querySelector('#intro-error').textContent=error.message;}});
  document.querySelector('#intro-name')?.addEventListener('input',event=>{userName=event.target.value.trim();rememberIntro();});
  document.querySelector('#intro-ai-later')?.addEventListener('click',()=>{introIndex++;renderIntro();});
  window.TOCRI18n={setLocale,getLocale:()=>locale,t,initOnboarding,apply};
